files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --input-bg: #0f3460;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', monospace;
  font-size: 16px;
  color: var(--text);
  padding: 1rem;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  box-shadow: 8px 8px 0 rgba(0,0,0,0.5);
  padding: 2rem;
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

h1 {
  margin: 0;
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.subtitle {
  margin: 0 0 0.5rem;
  text-align: center;
  font-size: 0.85rem;
  opacity: 0.7;
}

label {
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-top: 0.5rem;
}

input, select {
  font-family: inherit;
  font-size: 1rem;
  padding: 0.6rem;
  background: var(--input-bg);
  color: var(--text);
  border: 2px solid var(--accent);
  outline: none;
  width: 100%;
}

input:focus, select:focus {
  border-color: #fff;
  box-shadow: 0 0 0 2px var(--accent);
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  letter-spacing: 2px;
  padding: 0.8rem;
  margin-top: 0.5rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-bottom: 4px solid #a02a3f;
  cursor: pointer;
  transition: transform 0.05s, background 0.15s;
}

button:hover { background: #ff5c77; }
button:focus-visible { outline: 3px solid #fff; outline-offset: 2px; }
button:active { transform: translateY(2px); border-bottom-width: 2px; }

.result-box {
  margin-top: 1rem;
  padding: 1rem;
  background: var(--input-bg);
  border: 2px dashed var(--accent);
  text-align: center;
}

.result-label {
  display: block;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  opacity: 0.7;
  margin-bottom: 0.25rem;
}

#result {
  font-size: 1.8rem;
  font-weight: bold;
  color: var(--accent);
  word-break: break-all;
}

.formulas {
  margin-top: 1rem;
  font-size: 0.8rem;
  opacity: 0.7;
  line-height: 1.6;
}

.formulas p { margin: 0; }

@media (max-width: 400px) {
  .card { padding: 1.25rem; }
  h1 { font-size: 1.2rem; }
  #result { font-size: 1.4rem; }
}

const tempInput = document.getElementById('temperature');
const direction = document.getElementById('direction');
const convertBtn = document.getElementById('convert');
const result = document.getElementById('result');

function convert() {
  const raw = tempInput.value.trim();
  if (raw === '') {
    result.textContent = 'Error';
    return;
  }
  const x = Number(raw);
  if (!Number.isFinite(x)) {
    result.textContent = 'Error';
    return;
  }
  let out;
  if (direction.value === 'c-to-f') {
    out = x * 9 / 5 + 32;
  } else {
    out = (x - 32) * 5 / 9;
  }
  result.textContent = out.toFixed(2);
}

convertBtn.addEventListener('click', convert);

tempInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') convert();
});
